<?php

declare(strict_types=1);

use Illuminate\Routing\Route as RoutingRoute;
use Illuminate\Support\Facades\Artisan;
use Illuminate\Support\Facades\Route;

/*
 * The OpenAPI document generated by L5-Swagger must describe every
 * registered `api.v1.*` route (each HTTP method, PUT and PATCH separately)
 * with the bearer security requirement and the 401/403 error responses.
 */

/** @return array<string, mixed> */
function generatedSpec(): array
{
    expect(Artisan::call('l5-swagger:generate'))->toBe(0);

    $path = config('l5-swagger.defaults.paths.docs').DIRECTORY_SEPARATOR
        .config('l5-swagger.documentations.default.paths.docs_json');

    expect(is_file($path))->toBeTrue();

    $spec = json_decode((string) file_get_contents($path), true, flags: JSON_THROW_ON_ERROR);

    expect($spec)->toBeArray();

    return $spec;
}

/** @return list<array{0: string, 1: string}> [method (lowercase), "/uri"] */
function v1Operations(): array
{
    return collect(Route::getRoutes()->getRoutes())
        ->filter(fn (RoutingRoute $route): bool => str_starts_with((string) $route->getName(), 'api.v1.'))
        ->flatMap(fn (RoutingRoute $route): array => collect($route->methods())
            ->reject(fn (string $method): bool => $method === 'HEAD')
            ->map(fn (string $method): array => [strtolower($method), '/'.$route->uri()])
            ->all())
        ->values()
        ->all();
}

it('generates a valid spec with the bearer security scheme', function (): void {
    $spec = generatedSpec();

    expect($spec['openapi'])->toStartWith('3.')
        ->and($spec['info']['title'])->toBe('Finestro API')
        ->and($spec['components']['securitySchemes']['bearerAuth'])->toMatchArray([
            'type' => 'http',
            'scheme' => 'bearer',
        ])
        ->and(array_keys($spec['components']['responses']))
        ->toContain('Unauthorized', 'Forbidden', 'NotFound', 'ValidationError', 'TooManyRequests');
});

it('documents every api.v1 route with bearer security and 401/403 responses', function (): void {
    $spec = generatedSpec();
    $operations = v1Operations();

    expect($operations)->not->toBeEmpty();

    foreach ($operations as [$method, $uri]) {
        $operation = $spec['paths'][$uri][$method] ?? null;

        expect($operation)->toBeArray("{$method} {$uri} is missing from the spec");
        expect($operation['security'] ?? [])->toContain(['bearerAuth' => []]);
        expect(array_map(strval(...), array_keys($operation['responses'])))
            ->toContain('401', '403');
    }
});

it('documents wallet updates with a partial WalletUpdateInput body', function (): void {
    $spec = generatedSpec();
    $schema = $spec['components']['schemas']['WalletUpdateInput'] ?? null;

    expect($schema)->toBeArray()
        ->and($schema)->not->toHaveKey('required')
        ->and(array_keys($schema['properties']))
        ->toContain('company_name', 'company_document', 'credit_limit', 'closing_day', 'due_day');

    foreach (['put', 'patch'] as $method) {
        expect($spec['paths']['/api/v1/wallets/{wallet}'][$method]['requestBody']['content']['application/json']['schema']['$ref'])
            ->toBe('#/components/schemas/WalletUpdateInput');
    }
});

it('documents no operation outside the registered api.v1 routes', function (): void {
    $spec = generatedSpec();
    $registered = collect(v1Operations())->map(fn (array $op): string => $op[0].' '.$op[1])->all();

    foreach ($spec['paths'] as $uri => $item) {
        foreach (array_keys($item) as $method) {
            if (in_array($method, ['get', 'post', 'put', 'patch', 'delete'], true)) {
                expect($registered)->toContain("{$method} {$uri}");
            }
        }
    }
});
